export const envelope = [15, 28, 25];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;

  // --- PALETTE FROM THEME ---
  const planks = api.theme.wood?.planks || "minecraft:spruce_planks";
  const log = api.theme.wood?.log || "minecraft:spruce_log";
  const strippedLog = api.theme.wood?.stripped || "minecraft:stripped_spruce_log";
  const stairs = api.theme.wood?.stairs || "minecraft:spruce_stairs";
  const slab = api.theme.wood?.slab || "minecraft:spruce_slab";
  const fence = api.theme.wood?.fence || "minecraft:spruce_fence";
  const trapdoor = api.theme.wood?.trapdoor || "minecraft:spruce_trapdoor";

  // Palette helpers
  function getPlanks() {
    return planks;
  }
  function getLog(axis = "y") {
    const base = log.split("[")[0];
    return `${base}[axis=${axis}]`;
  }
  function getStripped(axis = "y") {
    const base = strippedLog.split("[")[0];
    return `${base}[axis=${axis}]`;
  }
  function getStairs(facing = "north", half = "bottom") {
    const base = stairs.split("[")[0];
    return `${base}[facing=${facing},half=${half}]`;
  }
  function getSlab(type = "bottom") {
    const base = slab.split("[")[0];
    return `${base}[type=${type}]`;
  }
  function getTrapdoor(facing = "north", half = "bottom", open = false) {
    const base = trapdoor.split("[")[0];
    return `${base}[facing=${facing},half=${half},open=${open}]`;
  }
  function getFence() {
    return fence;
  }

  // Bounds-checked placement
  function setBlock(x, y, z, block) {
    if (x >= 0 && x < sizeX && y >= 0 && y < sizeY && z >= 0 && z < sizeZ) {
      api.set(x, y, z, block);
    }
  }

  // Node-local seat plane
  const baseY = 5;

  // Track columns touching ground for Rule 6 conformance
  const groundColumns = new Set();
  function markGround(x, z) {
    groundColumns.add(`${x},${z}`);
  }

  // -------------------------------------------------------------
  // 1. SLED CHASSIS & SKID RUNNERS (Y = baseY to baseY + 2)
  // -------------------------------------------------------------

  // Longitudinal skid runners (Left: X=3, Center Keel: X=7, Right: X=11)
  for (let z = 2; z <= 22; z++) {
    for (const x of [3, 7, 11]) {
      markGround(x, z);
      setBlock(x, baseY + 1, z, getLog("z"));
    }
  }

  // Upturned front tips of sled runners (Z = 1)
  for (const x of [3, 7, 11]) {
    markGround(x, 1);
    setBlock(x, baseY + 1, 1, getStairs("north", "top"));
    setBlock(x, baseY + 2, 1, getStairs("south", "bottom"));
  }

  // Rear runner tips (Z = 23)
  for (const x of [3, 7, 11]) {
    markGround(x, 23);
    setBlock(x, baseY + 1, 23, getStairs("south", "top"));
    setBlock(x, baseY + 2, 23, getStairs("north", "bottom"));
  }

  // Transverse heavy cross-beams tying the skids together
  const crossBeamsZ = [3, 6, 9, 12, 15, 18, 21];
  for (const z of crossBeamsZ) {
    for (let x = 2; x <= 12; x++) {
      markGround(x, z);
      setBlock(x, baseY + 1, z, getLog("x"));
    }
  }

  // Sled Deck Planking (Y = baseY + 2)
  for (let z = 3; z <= 21; z++) {
    for (let x = 3; x <= 11; x++) {
      setBlock(x, baseY + 2, z, getPlanks());
    }
  }

  // Outer deck edge trim
  for (let z = 3; z <= 21; z++) {
    setBlock(2, baseY + 2, z, getStairs("east", "bottom"));
    setBlock(12, baseY + 2, z, getStairs("west", "bottom"));
  }

  // -------------------------------------------------------------
  // 2. SIX MONUMENTAL WAR WHEELS & AXLES
  // -------------------------------------------------------------
  const wheelCenters = [
    { z: 6 },  // Front axle
    { z: 12 }, // Middle axle
    { z: 18 }  // Rear axle
  ];

  for (const { z: wz } of wheelCenters) {
    // Axle log spanning through the chassis
    for (let x = 1; x <= 13; x++) {
      setBlock(x, baseY + 1, wz, getLog("x"));
    }

    // Wheels on Left (X=1) and Right (X=13)
    for (const wx of [1, 13]) {
      const isLeft = wx === 1;

      // Mark ground contact under wheel
      for (let dz = -1; dz <= 1; dz++) {
        markGround(wx, wz + dz);
      }

      // Wheel hub
      setBlock(wx, baseY + 1, wz, getStripped("x"));

      // Hubcap / axle pin
      const capX = isLeft ? 0 : 14;
      setBlock(capX, baseY + 1, wz, getTrapdoor(isLeft ? "west" : "east", "bottom", false));

      // 3x3 Wheel Rim
      setBlock(wx, baseY + 2, wz, getPlanks());
      setBlock(wx, baseY, wz, getPlanks());
      setBlock(wx, baseY + 1, wz - 1, getPlanks());
      setBlock(wx, baseY + 1, wz + 1, getPlanks());

      // Wheel curved corners
      setBlock(wx, baseY + 2, wz - 1, getStairs("south", "bottom"));
      setBlock(wx, baseY + 2, wz + 1, getStairs("north", "bottom"));
      setBlock(wx, baseY, wz - 1, getStairs("south", "top"));
      setBlock(wx, baseY, wz + 1, getStairs("north", "top"));

      // Wheel chocks on the ground
      markGround(wx, wz - 2);
      markGround(wx, wz + 2);
      setBlock(wx, baseY, wz - 2, getStairs("south", "bottom"));
      setBlock(wx, baseY, wz + 2, getStairs("north", "bottom"));
    }
  }

  // -------------------------------------------------------------
  // 3. TERRAIN CONFORMANCE PASS (Rule 6)
  // -------------------------------------------------------------
  for (const key of groundColumns) {
    const [gx, gz] = key.split(",").map(Number);
    const gh = api.heightAt(gx, gz);
    const groundY = Math.max(0, Math.min(sizeY - 1, baseY + Math.round(gh)));

    if (groundY < baseY) {
      // Ground drops away: extend sturdy log pier down to the terrain
      for (let y = groundY; y < baseY; y++) {
        setBlock(gx, y, gz, getLog("y"));
      }
    }
  }

  // -------------------------------------------------------------
  // 4. FOUR EQUINE LEGS (Y = baseY + 3 to baseY + 8)
  // -------------------------------------------------------------
  const legs = [
    { name: "FL", minX: 4, maxX: 5, minZ: 5, maxZ: 6, isFront: true, isLeft: true },
    { name: "FR", minX: 9, maxX: 10, minZ: 5, maxZ: 6, isFront: true, isLeft: false },
    { name: "RL", minX: 4, maxX: 5, minZ: 16, maxZ: 17, isFront: false, isLeft: true },
    { name: "RR", minX: 9, maxX: 10, minZ: 16, maxZ: 17, isFront: false, isLeft: false }
  ];

  for (const leg of legs) {
    // Hoof (Y = baseY + 3) - Flared footing
    for (let x = leg.minX; x <= leg.maxX; x++) {
      for (let z = leg.minZ; z <= leg.maxZ; z++) {
        setBlock(x, baseY + 3, z, getStripped("y"));
      }
    }
    if (leg.isFront) {
      setBlock(leg.minX, baseY + 3, leg.minZ - 1, getStairs("south", "bottom"));
      setBlock(leg.maxX, baseY + 3, leg.minZ - 1, getStairs("south", "bottom"));
    } else {
      setBlock(leg.minX, baseY + 3, leg.maxZ + 1, getStairs("north", "bottom"));
      setBlock(leg.maxX, baseY + 3, leg.maxZ + 1, getStairs("north", "bottom"));
    }
    const sideX = leg.isLeft ? leg.minX - 1 : leg.maxX + 1;
    const sideFacing = leg.isLeft ? "east" : "west";
    setBlock(sideX, baseY + 3, leg.minZ, getStairs(sideFacing, "bottom"));
    setBlock(sideX, baseY + 3, leg.maxZ, getStairs(sideFacing, "bottom"));

    // Cannon bone (Y = baseY + 4 to baseY + 5)
    for (let y = baseY + 4; y <= baseY + 5; y++) {
      const zOffset = !leg.isFront && y === baseY + 5 ? -1 : 0;
      for (let x = leg.minX; x <= leg.maxX; x++) {
        for (let z = leg.minZ + zOffset; z <= leg.maxZ + zOffset; z++) {
          setBlock(x, y, z, getStripped("y"));
        }
      }
    }

    // Knee (Front) / Hock (Rear) (Y = baseY + 6)
    for (let x = leg.minX; x <= leg.maxX; x++) {
      for (let z = leg.minZ; z <= leg.maxZ; z++) {
        setBlock(x, baseY + 6, z, getStripped("y"));
      }
    }
    if (leg.isFront) {
      setBlock(leg.minX, baseY + 6, leg.minZ - 1, getStairs("south", "bottom"));
      setBlock(leg.maxX, baseY + 6, leg.minZ - 1, getStairs("south", "bottom"));
    } else {
      setBlock(leg.minX, baseY + 6, leg.maxZ, getStairs("north", "bottom"));
      setBlock(leg.maxX, baseY + 6, leg.maxZ, getStairs("north", "bottom"));
    }

    // Thighs / Shoulders widening into the torso (Y = baseY + 7)
    const zSpan = leg.isFront ? [leg.minZ - 1, leg.maxZ] : [leg.minZ, leg.maxZ + 1];
    for (let x = leg.minX; x <= leg.maxX; x++) {
      for (let z = zSpan[0]; z <= zSpan[1]; z++) {
        setBlock(x, baseY + 7, z, getStripped("y"));
      }
    }

    // Diagonal shipwright timber knee-braces to sled deck
    const braceZ = leg.isFront ? leg.minZ - 1 : leg.maxZ + 1;
    const braceFacing = leg.isFront ? "south" : "north";
    for (let x = leg.minX; x <= leg.maxX; x++) {
      setBlock(x, baseY + 4, braceZ, getStairs(braceFacing, "bottom"));
      setBlock(x, baseY + 5, braceZ, getFence());
    }
  }

  // -------------------------------------------------------------
  // 5. HOLLOW TORSO & SHIP-HULL BELLY (Y = 12 to 20)
  // -------------------------------------------------------------
  // Interior Chamber bounds: min=[5, 13, 7], max=[9, 17, 15]

  // Layer Y = 12 (baseY + 7): Underbelly Floor & Central Keel
  for (let z = 6; z <= 16; z++) {
    for (let x = 5; x <= 9; x++) {
      // Keel beam in center
      if (x === 7) {
        setBlock(x, 12, z, getLog("z"));
      } else {
        setBlock(x, 12, z, getPlanks());
      }
    }
    // Underbelly side curves
    setBlock(4, 12, z, getStairs("east", "top"));
    setBlock(10, 12, z, getStairs("west", "top"));
  }

  // Underbelly chest and rump curves
  for (let x = 5; x <= 9; x++) {
    setBlock(x, 12, 5, getStairs("south", "top"));
    setBlock(x, 12, 17, getStairs("north", "top"));
  }

  // UNLATCHED TRAPDOOR SEAM in the belly (X=7, Z=11)
  setBlock(7, 12, 11, getTrapdoor("north", "bottom", true));
  // Hanging rope ladder beginning to emerge!
  setBlock(7, 11, 11, getFence());
  setBlock(7, 10, 11, getTrapdoor("north", "top", false));
  setBlock(7, 9, 11, getFence());
  setBlock(7, 8, 11, getTrapdoor("north", "top", false));

  // Layers Y = 13 to 17: Hull Walls enclosing the hollow interior
  for (let y = 13; y <= 17; y++) {
    // Left and Right Flanks
    for (let z = 6; z <= 16; z++) {
      const isRib = z % 2 === 0;

      if (y === 13 || y === 17) {
        // Inward curvature at bottom and top of flank
        setBlock(4, y, z, isRib ? getStripped("y") : getPlanks());
        setBlock(10, y, z, isRib ? getStripped("y") : getPlanks());
      } else {
        // Bulging midsection of the hull
        setBlock(3, y, z, isRib ? getStripped("y") : getPlanks());
        setBlock(11, y, z, isRib ? getStripped("y") : getPlanks());
        // Interior structural backing
        setBlock(4, y, z, getPlanks());
        setBlock(10, y, z, getPlanks());

        // Covert soldier peepholes in hull planking at Y = 15
        if (y === 15 && (z === 8 || z === 12 || z === 14)) {
          setBlock(3, y, z, getTrapdoor("east", "bottom", false));
          setBlock(11, y, z, getTrapdoor("west", "bottom", false));
        }
      }
    }

    // Front Chest Wall (Z = 5..6)
    for (let x = 5; x <= 9; x++) {
      setBlock(x, y, 6, getPlanks());
    }
    // Outer chest curvature
    for (let x = 6; x <= 8; x++) {
      setBlock(x, y, 5, getStripped("y"));
    }
    if (y >= 13 && y <= 15) {
      setBlock(7, y, 4, getStairs("south", "bottom"));
    }

    // Rear Rump Wall (Z = 16..17)
    for (let x = 5; x <= 9; x++) {
      setBlock(x, y, 16, getPlanks());
    }
    // Outer rump curvature
    for (let x = 6; x <= 8; x++) {
      setBlock(x, y, 17, getStripped("y"));
    }
    if (y >= 13 && y <= 16) {
      setBlock(7, y, 18, getStairs("north", "bottom"));
    }
  }

  // Layer Y = 18: Chamber Ceiling & Back Deck
  for (let z = 6; z <= 16; z++) {
    for (let x = 5; x <= 9; x++) {
      setBlock(x, 18, z, getPlanks());
    }
    setBlock(4, 18, z, getStairs("west", "bottom"));
    setBlock(10, 18, z, getStairs("east", "bottom"));
  }
  for (let x = 5; x <= 9; x++) {
    setBlock(x, 18, 5, getPlanks());
    setBlock(x, 18, 17, getStairs("south", "bottom"));
  }

  // Layer Y = 19: Horse Back & Withers Base
  for (let z = 6; z <= 16; z++) {
    for (let x = 6; x <= 8; x++) {
      setBlock(x, 19, z, getStripped("z"));
    }
    setBlock(5, 19, z, getStairs("west", "bottom"));
    setBlock(9, 19, z, getStairs("east", "bottom"));
  }
  for (let x = 6; x <= 8; x++) {
    setBlock(x, 19, 5, getStripped("y"));
    setBlock(x, 19, 17, getStairs("north", "bottom"));
  }

  // Layer Y = 20: Spine Ridge & Withers
  for (let z = 7; z <= 15; z++) {
    setBlock(7, 20, z, getSlab("bottom"));
  }
  for (let x = 6; x <= 8; x++) {
    setBlock(x, 20, 5, getStripped("y"));
    setBlock(x, 20, 6, getStripped("y"));
  }

  // -------------------------------------------------------------
  // 6. NECK, MANE & SCULPTED HEAD (Y = 19 to 26)
  // -------------------------------------------------------------

  // Neck Base (Y = 19)
  for (let z = 3; z <= 5; z++) {
    for (let x = 5; x <= 9; x++) {
      setBlock(x, 19, z, getStripped("y"));
    }
  }
  for (let x = 6; x <= 8; x++) {
    setBlock(x, 19, 2, getStairs("south", "top"));
  }

  // Neck Core & Mane (Y = 20)
  for (let z = 3; z <= 5; z++) {
    for (let x = 6; x <= 8; x++) {
      setBlock(x, 20, z, getStripped("y"));
    }
    setBlock(5, 20, z, getStairs("west", "bottom"));
    setBlock(9, 20, z, getStairs("east", "bottom"));
  }
  for (let x = 6; x <= 8; x++) {
    setBlock(x, 20, 2, getStairs("south", "top"));
  }
  setBlock(7, 20, 6, getStairs("north", "bottom")); // Mane crest

  // Neck Rising (Y = 21)
  for (let z = 2; z <= 4; z++) {
    for (let x = 6; x <= 8; x++) {
      setBlock(x, 21, z, getStripped("y"));
    }
    setBlock(5, 21, z, getStairs("west", "bottom"));
    setBlock(9, 21, z, getStairs("east", "bottom"));
  }
  for (let x = 6; x <= 8; x++) {
    setBlock(x, 21, 1, getStairs("south", "top"));
  }
  setBlock(7, 21, 5, getStairs("north", "bottom")); // Mane crest

  // Upper Neck & Jowl (Y = 22)
  for (let z = 2; z <= 4; z++) {
    for (let x = 6; x <= 8; x++) {
      setBlock(x, 22, z, getStripped("y"));
    }
  }
  // Muzzle underside / chin
  for (let x = 6; x <= 8; x++) {
    setBlock(x, 22, 1, getStripped("z"));
    setBlock(x, 22, 0, getStairs("south", "top"));
  }
  setBlock(7, 22, 5, getStairs("north", "bottom")); // Mane crest

  // Main Head & Muzzle (Y = 23)
  // Muzzle & Nostrils
  setBlock(6, 23, 0, getStairs("east", "bottom"));
  setBlock(7, 23, 0, getSlab("bottom"));
  setBlock(8, 23, 0, getStairs("west", "bottom"));
  for (let x = 6; x <= 8; x++) {
    setBlock(x, 23, 1, getPlanks());
  }
  // Cheeks / Jaw
  for (let z = 2; z <= 3; z++) {
    for (let x = 6; x <= 8; x++) {
      setBlock(x, 23, z, getStripped("x"));
    }
  }
  // Decorative cheek rounds / bridle fittings
  setBlock(5, 23, 2, getTrapdoor("east", "bottom", false));
  setBlock(9, 23, 2, getTrapdoor("west", "bottom", false));
  setBlock(7, 23, 4, getStairs("north", "bottom")); // Mane crest

  // Forehead & Brow (Y = 24)
  for (let z = 1; z <= 2; z++) {
    for (let x = 6; x <= 8; x++) {
      setBlock(x, 24, z, getStripped("z"));
    }
  }
  // Eyes
  setBlock(5, 24, 2, getStairs("south", "bottom"));
  setBlock(9, 24, 2, getStairs("south", "bottom"));
  // Forelock crest
  for (let x = 6; x <= 8; x++) {
    setBlock(x, 24, 3, getStripped("y"));
  }
  setBlock(7, 24, 4, getSlab("bottom")); // Mane top

  // Crown & Forelock (Y = 25)
  setBlock(7, 25, 1, getStairs("south", "bottom"));
  setBlock(7, 25, 2, getPlanks());
  // Ear bases
  setBlock(6, 25, 3, getStairs("north", "bottom"));
  setBlock(8, 25, 3, getStairs("north", "bottom"));

  // Pointed Wooden Ears (Y = 26)
  setBlock(6, 26, 3, getFence());
  setBlock(8, 26, 3, getFence());

  // -------------------------------------------------------------
  // 7. FLOWING TIMBER TAIL (Y = 8 to 19, Z = 18 to 22)
  // -------------------------------------------------------------
  setBlock(7, 19, 18, getStripped("z"));
  setBlock(7, 18, 19, getStairs("south", "bottom"));

  for (let x = 6; x <= 8; x++) {
    setBlock(x, 17, 20, getStripped("y"));
    setBlock(x, 16, 20, getPlanks());
    setBlock(x, 15, 21, getStripped("y"));
  }
  setBlock(5, 16, 20, getStairs("east", "bottom"));
  setBlock(9, 16, 20, getStairs("west", "bottom"));

  setBlock(7, 14, 21, getPlanks());
  setBlock(6, 14, 21, getFence());
  setBlock(8, 14, 21, getFence());

  setBlock(7, 13, 21, getStripped("y"));
  setBlock(7, 13, 22, getStripped("y"));

  for (let x = 6; x <= 8; x++) {
    setBlock(x, 12, 22, getPlanks());
  }
  setBlock(7, 11, 22, getStairs("north", "bottom"));
  setBlock(7, 10, 22, getFence());
  setBlock(7, 9, 22, getFence());
  setBlock(7, 8, 22, getTrapdoor("north", "top", false));

  // -------------------------------------------------------------
  // 8. TOWING TETHERS, WINCHES & CITADEL DETAILS
  // -------------------------------------------------------------

  // Front bollards on the sled platform
  for (const x of [3, 7, 11]) {
    setBlock(x, baseY + 3, 2, getStripped("y"));
    setBlock(x, baseY + 4, 2, getTrapdoor("north", "bottom", false));
  }

  // Heavy tow ropes stretching north towards the Scaean gate
  for (let z = 0; z <= 1; z++) {
    setBlock(3, baseY + 2, z, getFence());
    setBlock(11, baseY + 2, z, getFence());
  }
  setBlock(7, baseY + 1, 0, getLog("z"));

  // Bronze lanterns on the four corners of the sled platform
  const lanternCorners = [
    { x: 2, z: 3 },
    { x: 12, z: 3 },
    { x: 2, z: 21 },
    { x: 12, z: 21 }
  ];
  for (const { x, z } of lanternCorners) {
    setBlock(x, baseY + 3, z, getFence());
    setBlock(x, baseY + 4, z, "minecraft:lantern[hanging=false]");
  }

  // Flank staging ladder for Greek siege builders
  for (let y = baseY + 2; y <= baseY + 6; y++) {
    setBlock(2, y, 10, getFence());
  }

  // -------------------------------------------------------------
  // RETURN RESULT
  // -------------------------------------------------------------
  return {
    name: "trojan_horse",
    seatY: 5,
    anchors: {
      front: [7, 5, 0],
      door: [7, 5, 2]
    },
    interiors: [
      {
        min: [5, 13, 7],
        max: [9, 17, 15],
        kind: "hold"
      }
    ]
  };
}
